svg.script:
(function () {
  var seasonAngle = 40;
  var timeAngle = 105;
  var activeDial = null;
  var currentWeather = "clear";
  var svg = document.documentElement;

  var ids = [
    "skyTop", "skyMid", "skyBottom", "farHillTop", "farHillBottom",
    "nearHillTop", "nearHillBottom", "lakeTop", "lakeMid", "lakeBottom",
    "foregroundTop", "foregroundBottom", "sideMountain", "mainMountain",
    "sunCore", "sunHalo", "sunHalo1", "sunHalo2", "sunHalo3", "sunHalo4",
    "clouds", "waterFlow", "horizonMist", "ripples", "snowCap",
    "seasonDots", "weatherDim", "weatherLayer", "seasonKnob", "timeKnob", "seasonArc", "timeArc",
    "seasonValue", "timeValue"
  ].reduce(function (acc, id) {
    acc[id] = document.getElementById(id);
    return acc;
  }, {});

  var seasons = [
    {
      name: "Spring",
      skyTop: "#d9f0e6", skyMid: "#f3dfcf", skyBottom: "#eec2a7",
      farTop: "#a8c9b3", farBottom: "#80aa9c",
      side: "#6f9e90", nearTop: "#4f7770", nearBottom: "#31595a",
      lakeTop: "#b8d7cf", lakeMid: "#9dc8bf", lakeBottom: "#6f9997",
      foreTop: "#2d5850", foreBottom: "#173a38",
      dots: 0.72, snow: 0
    },
    {
      name: "Summer",
      skyTop: "#b8e6ea", skyMid: "#e6ecd0", skyBottom: "#f0d0a4",
      farTop: "#8fb8a2", farBottom: "#689d8d",
      side: "#5d8d80", nearTop: "#426f67", nearBottom: "#284f51",
      lakeTop: "#a9d7d2", lakeMid: "#83bdb7", lakeBottom: "#5f9698",
      foreTop: "#23534a", foreBottom: "#153c37",
      dots: 0.25, snow: 0
    },
    {
      name: "Autumn",
      skyTop: "#f0b07f", skyMid: "#e8b37a", skyBottom: "#bf735d",
      farTop: "#d6a35f", farBottom: "#b67f4a",
      side: "#a96343", nearTop: "#795638", nearBottom: "#483a2c",
      lakeTop: "#cfb98c", lakeMid: "#b69d75", lakeBottom: "#887661",
      foreTop: "#5a3f29", foreBottom: "#2f2b23",
      dots: 0.65, snow: 0
    },
    {
      name: "Winter",
      skyTop: "#d4e3e9", skyMid: "#d7dce4", skyBottom: "#c5b6ba",
      farTop: "#bacbd0", farBottom: "#95adb5",
      side: "#849aa3", nearTop: "#5e727b", nearBottom: "#334951",
      lakeTop: "#bfd4d8", lakeMid: "#a8bec6", lakeBottom: "#829da8",
      foreTop: "#2b454d", foreBottom: "#182f38",
      dots: 0, snow: 0.82
    }
  ];

  var times = [
    { name: "Night", top: "#15203a", mid: "#293651", bottom: "#566075", sun: "#dbeaff", halo: "#8fb0d8", flow: "#cfe8ff", cloud: 0.18 },
    { name: "Dawn", top: "#c8e6ea", mid: "#f3d7c7", bottom: "#e4af95", sun: "#ffe0a0", halo: "#f1a985", flow: "#e8f5ef", cloud: 0.3 },
    { name: "Noon", top: "#9bd5e5", mid: "#d8f0ed", bottom: "#f1dfc0", sun: "#fff1b8", halo: "#f7d894", flow: "#f4fffb", cloud: 0.24 },
    { name: "Dusk", top: "#e39b84", mid: "#c0787b", bottom: "#5a4569", sun: "#ffbd82", halo: "#e98176", flow: "#ffe7d5", cloud: 0.2 },
    { name: "Night", top: "#15203a", mid: "#293651", bottom: "#566075", sun: "#dbeaff", halo: "#8fb0d8", flow: "#cfe8ff", cloud: 0.18 }
  ];

  var weathers = {
    clear: { dim: 0, cloudBoost: 0, sunScale: 1, flowBoost: 0 },
    rain: { dim: 0.16, cloudBoost: 0.34, sunScale: 0.58, flowBoost: 0.2 },
    snow: { dim: 0.12, cloudBoost: 0.28, sunScale: 0.68, flowBoost: 0.08 },
    cloudy: { dim: 0.18, cloudBoost: 0.42, sunScale: 0.48, flowBoost: 0.02 }
  };

  function hexToRgb(hex) {
    var value = hex.replace("#", "");
    return [
      parseInt(value.slice(0, 2), 16),
      parseInt(value.slice(2, 4), 16),
      parseInt(value.slice(4, 6), 16)
    ];
  }

  function rgbToHex(rgb) {
    return "#" + rgb.map(function (value) {
      var part = Math.max(0, Math.min(255, Math.round(value))).toString(16);
      return part.length === 1 ? "0" + part : part;
    }).join("");
  }

  function mix(a, b, t) {
    var ca = hexToRgb(a);
    var cb = hexToRgb(b);
    return rgbToHex(ca.map(function (value, index) {
      return value + (cb[index] - value) * t;
    }));
  }

  function pick(list, angle) {
    var position = (angle % 360) / 360 * (list.length - 1);
    var index = Math.floor(position);
    var next = Math.min(index + 1, list.length - 1);
    return { a: list[index], b: list[next], t: position - index };
  }

  function blendSeason(angle) {
    var chosen = pick(seasons.concat([seasons[0]]), angle);
    var result = { name: chosen.t < 0.5 ? chosen.a.name : chosen.b.name };
    Object.keys(chosen.a).forEach(function (key) {
      if (key === "name") return;
      result[key] = typeof chosen.a[key] === "number"
        ? chosen.a[key] + (chosen.b[key] - chosen.a[key]) * chosen.t
        : mix(chosen.a[key], chosen.b[key], chosen.t);
    });
    return result;
  }

  function blendTime(angle) {
    var chosen = pick(times, angle);
    var result = { name: chosen.t < 0.5 ? chosen.a.name : chosen.b.name };
    ["top", "mid", "bottom", "sun", "halo", "flow"].forEach(function (key) {
      result[key] = mix(chosen.a[key], chosen.b[key], chosen.t);
    });
    result.cloud = chosen.a.cloud + (chosen.b.cloud - chosen.a.cloud) * chosen.t;
    return result;
  }

  function setStop(id, color) {
    if (ids[id]) ids[id].setAttribute("stop-color", color);
  }

  function setSunPosition(angle, sunScale) {
    var rad = (angle - 180) * Math.PI / 180;
    var x = 960 + 560 * Math.sin(rad);
    var y = 650 - 300 * Math.cos(rad);
    var day = Math.max(0, Math.cos(rad));
    var opacity = (0.16 + day * 0.8) * sunScale;
    ["sunCore", "sunHalo1", "sunHalo2", "sunHalo3", "sunHalo4"].forEach(function (id) {
      ids[id].setAttribute("cx", x.toFixed(1));
      ids[id].setAttribute("cy", y.toFixed(1));
    });
    ids.sunCore.setAttribute("opacity", opacity.toFixed(2));
    ids.sunHalo.setAttribute && ids.sunHalo.setAttribute("opacity", ((0.22 + day * 0.5) * sunScale).toFixed(2));
  }

  function makeSvg(name) {
    return document.createElementNS("http://www.w3.org/2000/svg", name);
  }

  function randomBetween(min, max) {
    return min + Math.random() * (max - min);
  }

  function createClouds() {
    while (ids.clouds.firstChild) {
      ids.clouds.removeChild(ids.clouds.firstChild);
    }

    var count = currentWeather === "cloudy" ? 8 : currentWeather === "clear" ? 6 : 7;
    var segmentWidth = 1920 / count;
    for (var i = 0; i < count; i += 1) {
      var cloud = makeSvg("g");
      var y = randomBetween(145, 325) + (i % 2) * randomBetween(12, 34);
      var segmentCenter = segmentWidth * (i + 0.5);
      var startX = segmentCenter + randomBetween(-segmentWidth * 0.22, segmentWidth * 0.22);
      var drift = randomBetween(80, 210) * (Math.random() > 0.5 ? 1 : -1);
      var lift = randomBetween(-12, 12);
      var scale = randomBetween(0.58, 1.26);
      var duration = randomBetween(34, 68).toFixed(1) + "s";

      cloud.setAttribute("opacity", randomBetween(0.45, currentWeather === "clear" ? 0.85 : 0.98).toFixed(2));

      var motion = makeSvg("animateTransform");
      motion.setAttribute("attributeName", "transform");
      motion.setAttribute("type", "translate");
      motion.setAttribute("dur", duration);
      motion.setAttribute("repeatCount", "indefinite");
      motion.setAttribute("values", [
        startX.toFixed(1) + " " + y.toFixed(1),
        (startX + drift * 0.45).toFixed(1) + " " + (y + lift).toFixed(1),
        (startX + drift).toFixed(1) + " " + (y - lift * 0.35).toFixed(1),
        (startX + drift * 0.45).toFixed(1) + " " + (y + lift * 0.45).toFixed(1),
        startX.toFixed(1) + " " + y.toFixed(1)
      ].join(";"));
      cloud.appendChild(motion);

      [
        [-70, 5, 145, 26],
        [20, -6, 185, 34],
        [118, 8, 108, 24],
        [-158, 14, 78, 18]
      ].forEach(function (blob) {
        var ellipse = makeSvg("ellipse");
        ellipse.setAttribute("cx", (blob[0] * scale).toFixed(1));
        ellipse.setAttribute("cy", (blob[1] * scale).toFixed(1));
        ellipse.setAttribute("rx", (blob[2] * scale).toFixed(1));
        ellipse.setAttribute("ry", (blob[3] * scale).toFixed(1));
        ellipse.setAttribute("fill", "#ffffff");
        cloud.appendChild(ellipse);
      });

      ids.clouds.appendChild(cloud);
    }
  }

  function createWeather() {
    while (ids.weatherLayer.firstChild) {
      ids.weatherLayer.removeChild(ids.weatherLayer.firstChild);
    }

    if (currentWeather === "rain") {
      var rain = makeSvg("g");
      rain.setAttribute("stroke", "#d7edf5");
      rain.setAttribute("stroke-linecap", "round");
      rain.setAttribute("opacity", "0.58");
      for (var i = 0; i < 95; i += 1) {
        var x = (i / 95) * 2040 + randomBetween(-60, 60) - 80;
        var y = randomBetween(-220, 1060);
        var length = randomBetween(42, 78);
        var drop = makeSvg("line");
        drop.setAttribute("x1", x.toFixed(1));
        drop.setAttribute("y1", y.toFixed(1));
        drop.setAttribute("x2", (x - length * 0.28).toFixed(1));
        drop.setAttribute("y2", (y + length).toFixed(1));
        drop.setAttribute("stroke-width", randomBetween(1.4, 2.7).toFixed(1));

        var fall = makeSvg("animateTransform");
        fall.setAttribute("attributeName", "transform");
        fall.setAttribute("type", "translate");
        fall.setAttribute("from", "0 -160");
        fall.setAttribute("to", "0 1180");
        fall.setAttribute("dur", randomBetween(1.0, 1.9).toFixed(2) + "s");
        fall.setAttribute("begin", "-" + randomBetween(0, 1.9).toFixed(2) + "s");
        fall.setAttribute("repeatCount", "indefinite");
        drop.appendChild(fall);
        rain.appendChild(drop);
      }
      ids.weatherLayer.appendChild(rain);
    }

    if (currentWeather === "snow") {
      var snow = makeSvg("g");
      snow.setAttribute("fill", "#f8fcff");
      snow.setAttribute("opacity", "0.76");
      for (var j = 0; j < 120; j += 1) {
        var flake = makeSvg("circle");
        var fx = (j / 120) * 2040 + randomBetween(-80, 80) - 60;
        var fy = randomBetween(-260, 1060);
        var drift = randomBetween(-90, 90);
        flake.setAttribute("cx", fx.toFixed(1));
        flake.setAttribute("cy", fy.toFixed(1));
        flake.setAttribute("r", randomBetween(2.0, 5.2).toFixed(1));
        flake.setAttribute("opacity", randomBetween(0.32, 0.88).toFixed(2));

        var snowFall = makeSvg("animateTransform");
        snowFall.setAttribute("attributeName", "transform");
        snowFall.setAttribute("type", "translate");
        snowFall.setAttribute("values", "0 -180;" + drift.toFixed(1) + " 1120;0 -180");
        snowFall.setAttribute("dur", randomBetween(8, 16).toFixed(1) + "s");
        snowFall.setAttribute("begin", "-" + randomBetween(0, 12).toFixed(1) + "s");
        snowFall.setAttribute("repeatCount", "indefinite");
        flake.appendChild(snowFall);
        snow.appendChild(flake);
      }
      ids.weatherLayer.appendChild(snow);
    }
  }

  function arcPath(radius, angle) {
    var end = polar(radius, angle);
    var large = angle > 180 ? 1 : 0;
    return "M 0 " + -radius + " A " + radius + " " + radius + " 0 " + large + " 1 " + end.x + " " + end.y;
  }

  function polar(radius, angle) {
    var rad = (angle - 90) * Math.PI / 180;
    return { x: radius * Math.cos(rad), y: radius * Math.sin(rad) };
  }

  function updateDial(name, angle, label) {
    var point = polar(62, angle);
    ids[name + "Knob"].setAttribute("cx", point.x.toFixed(1));
    ids[name + "Knob"].setAttribute("cy", point.y.toFixed(1));
    ids[name + "Arc"].setAttribute("d", angle < 0.5 ? "" : arcPath(62, angle));
    ids[name + "Value"].textContent = label;
  }

  function applyScene() {
    var s = blendSeason(seasonAngle);
    var t = blendTime(timeAngle);
    var w = weathers[currentWeather];
    var rad = (timeAngle - 180) * Math.PI / 180;
    var day = Math.max(0, Math.cos(rad));
    var nightMix = Math.min(0.72, (1 - day) * 0.44 + w.dim * 0.42);

    var skySeasonStrength = 0.08 + day * 0.14;
    setStop("skyTop", mix(t.top, s.skyTop, skySeasonStrength));
    setStop("skyMid", mix(t.mid, s.skyMid, skySeasonStrength));
    setStop("skyBottom", mix(t.bottom, s.skyBottom, skySeasonStrength));
    setStop("farHillTop", mix(s.farTop, "#17263a", nightMix));
    setStop("farHillBottom", mix(s.farBottom, "#182d38", nightMix));
    setStop("nearHillTop", mix(s.nearTop, "#111f2d", nightMix));
    setStop("nearHillBottom", mix(s.nearBottom, "#0d1b24", nightMix));
    setStop("lakeTop", mix(s.lakeTop, t.top, 0.18 + nightMix * 0.4));
    setStop("lakeMid", mix(s.lakeMid, t.mid, 0.16 + nightMix * 0.36));
    setStop("lakeBottom", mix(s.lakeBottom, "#172b36", nightMix));
    setStop("foregroundTop", mix(s.foreTop, "#0d1c24", nightMix));
    setStop("foregroundBottom", mix(s.foreBottom, "#071219", nightMix));

    ids.sideMountain.setAttribute("fill", mix(s.side, "#122633", nightMix));
    ids.mainMountain.setAttribute("opacity", (0.94 - nightMix * 0.1).toFixed(2));
    ids.sunCore.setAttribute("fill", t.sun);
    ["sunHalo1", "sunHalo2", "sunHalo3", "sunHalo4"].forEach(function (id) {
      ids[id].setAttribute("fill", t.halo);
    });
    ids.waterFlow.setAttribute("stroke", t.flow);
    ids.waterFlow.setAttribute("opacity", (0.34 + w.flowBoost).toFixed(2));
    ids.clouds.setAttribute("opacity", Math.min(0.84, t.cloud + w.cloudBoost).toFixed(2));
    ids.horizonMist.setAttribute("fill", mix("#d7e4df", t.bottom, 0.2));
    ids.ripples.setAttribute("opacity", (0.12 + day * 0.14).toFixed(2));
    ids.weatherDim.setAttribute("opacity", w.dim.toFixed(2));
    ids.snowCap.setAttribute("opacity", (Math.max(s.snow, currentWeather === "snow" ? 0.78 : 0) * (0.6 + day * 0.4)).toFixed(2));
    ids.seasonDots.setAttribute("opacity", (s.dots * (0.35 + day * 0.65)).toFixed(2));

    setSunPosition(timeAngle, w.sunScale);
    updateDial("season", seasonAngle, s.name);
    updateDial("time", timeAngle, t.name);
  }

  function updateWeatherButtons() {
    Array.prototype.forEach.call(document.querySelectorAll(".weather-button"), function (button) {
      if (button.getAttribute("data-weather") === currentWeather) {
        button.classList.add("active");
      } else {
        button.classList.remove("active");
      }
    });
  }

  function setWeather(value) {
    currentWeather = value;
    createClouds();
    createWeather();
    updateWeatherButtons();
    applyScene();
  }

  function angleFromEvent(evt, dial) {
    var matrix = dial.getScreenCTM();
    var point = svg.createSVGPoint();
    point.x = evt.clientX;
    point.y = evt.clientY;
    point = point.matrixTransform(matrix.inverse());
    var angle = Math.atan2(point.y, point.x) * 180 / Math.PI + 90;
    return (angle + 360) % 360;
  }

  function start(evt) {
    var dial = evt.target.closest(".dial");
    if (!dial) return;
    activeDial = dial;
    evt.preventDefault();
    move(evt);
  }

  function move(evt) {
    if (!activeDial) return;
    var value = angleFromEvent(evt, activeDial);
    if (activeDial.getAttribute("data-control") === "season") {
      seasonAngle = value;
    } else {
      timeAngle = value;
    }
    applyScene();
  }

  function end() {
    activeDial = null;
  }

  svg.addEventListener("pointerdown", start);
  svg.addEventListener("pointermove", move);
  svg.addEventListener("pointerup", end);
  svg.addEventListener("pointerleave", end);
  Array.prototype.forEach.call(document.querySelectorAll(".weather-button"), function (button) {
    button.addEventListener("pointerdown", function (evt) {
      evt.preventDefault();
      evt.stopPropagation();
      setWeather(button.getAttribute("data-weather"));
    });
  });
  createClouds();
  createWeather();
  updateWeatherButtons();
  applyScene();
}());
